package run.ikaros.music;
import java.util.UUID; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.web.bind.annotation.PathVariable; import org.springframework.web.bind.annotation.PostMapping; import org.springframework.web.bind.annotation.RequestHeader; import org.springframework.web.bind.annotation.RequestMapping; import org.springframework.web.bind.annotation.RestController; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/music/tracks/{trackId}/metadata") public class MusicMetadataRecognitionController { private final MusicMetadataRecognitionService service; public MusicMetadataRecognitionController(MusicMetadataRecognitionService service){this.service=service;} @PostMapping("/recognize") public Mono<MusicMetadataCandidateView> recognize(@RequestHeader("X-Ikaros-Actor-Id") UUID ownerId,@PathVariable UUID trackId){return service.recognize(ownerId,trackId);} @GetMapping("/candidates") public Flux<MusicMetadataCandidateView> list(@RequestHeader("X-Ikaros-Actor-Id") UUID ownerId,@PathVariable UUID trackId){return service.list(ownerId,trackId);} }
